package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.Closeable;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.*;

/**
 * Unit tests for MappingIterator#hasNextValue
 */
public class MappingIterator_hasNextValue_TriageGen2Test {

    private MappingIterator<Object> iterator;
    private JsonParser mockParser;

    // Constants to match internal implementation if possible, 
    // otherwise we rely on the state transitions triggered by the logic.
    private static final int STATE_CLOSED = 0;
    private static final int STATE_NEED_RESYNC = 1;
    private static final int STATE_MAY_HAVE_VALUE = 2;
    private static final int STATE_HAS_VALUE = 3;

    @Before
    public void setUp() throws Exception {
        mockParser = mock(JsonParser.class);
        // We need to instantiate MappingIterator. Since it's often created via a factory,
        // we'll use reflection to mock/stub the necessary fields for this specific test.
        iterator = mock(MappingIterator.class, Mockito.CALLS_REAL_METHODS);

        setInternalState(iterator, "_parser", mockParser);
        setInternalState(iterator, "_state", STATE_MAY_HAVE_VALUE);
        setInternalState(iterator, "_closeParser", false);
    }

    private void setInternalState(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private void setState(int state) throws Exception {
        setInternalState(iterator, "_state", state);
    }

    @Test
    public void testHasNextValue_StateClosed() throws IOException, NoSuchFieldException, IllegalAccessException {
        setState(STATE_CLOSED);
        assertFalse(iterator.hasNextValue());
    }

    @Test
    public void testHasNextValue_StateNeedResync_ThenHasValue() throws IOException, NoSuchFieldException, IllegalAccessException {
        setState(STATE_NEED_RESYNC);
        // Mock _resync behavior is implicit as it's a protected method in the same class.
        // We simulate the fall-through to STATE_MAY_HAVE_VALUE
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.START_OBJECT);

        assertTrue(iterator.hasNextValue());
        assertEquals(STATE_HAS_VALUE, getInternalState(iterator, "_state"));
    }

    @Test
    public void testHasNextValue_StateMayHaveValue_TokenNotNull() throws IOException, NoSuchFieldException, IllegalAccessException {
        setState(STATE_MAY_HAVE_VALUE);
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.FIELD_NAME);

        assertTrue(iterator.hasNextValue());
        assertEquals(STATE_HAS_VALUE, getInternalState(iterator, "_state"));
        verify(mockParser, never()).nextToken();
    }

    @Test
    public void testHasNextValue_StateMayHaveValue_TokenNull_NextTokenNotNull() throws IOException, NoSuchFieldException, IllegalAccessException {
        setState(STATE_MAY_HAVE_VALUE);
        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.START_ARRAY);

        assertTrue(iterator.hasNextValue());
        assertEquals(STATE_HAS_VALUE, getInternalState(iterator, "_state"));
    }

    @Test
    public void testHasNextValue_StateMayHaveValue_TokenNull_NextTokenEndArray() throws IOException, NoSuchFieldException, IllegalAccessException {
        setState(STATE_MAY_HAVE_VALUE);
        setInternalState(iterator, "_closeParser", true);
        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.END_ARRAY);

        assertTrue(iterator.hasNextValue());
        assertEquals(STATE_CLOSED, getInternalState(iterator, "_state"));
        verify(mockParser).close();
    }

    @Test
    public void testHasNextValue_StateMayHaveValue_TokenNull_NextTokenNull() throws IOException, NoSuchFieldException, IllegalAccessException {
        setState(STATE_MAY_HAVE_VALUE);
        setInternalState(iterator, "_closeParser", false);
        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(null);

        assertTrue(iterator.hasNextValue());
        assertEquals(STATE_CLOSED, getInternalState(iterator, "_state"));
        verify(mockParser, never()).close();
    }

    @Test
    public void testHasNextValue_StateHasValue() throws IOException, NoSuchFieldException, IllegalAccessException {
        setState(STATE_HAS_VALUE);
        // In STATE_HAS_VALUE, it falls through to the end of the switch and returns true.
        assertTrue(iterator.hasNextValue());
    }

    private Object getInternalState(Object target, String fieldName) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(target);
    }
}
